// Decides which of two selectors wins a conflict
function winner(a, b) {
  const scoreA = specificity(a);
  const scoreB = specificity(b);
  if (scoreA > scoreB) return `${a} wins`;
  if (scoreB > scoreA) return `${b} wins`;
  return "tie — later rule wins";
}
